<svelte:options customElement={{tag:'compact-audio-browser',props:{catalog:{type:'Array'},queue:{type:'Array'},theme:{type:'String'},selectedUrl:{type:'String'},playbackMode:{type:'String'},mix:{type:'Object'}}}} />
<script lang="ts">
 import {Play,Plus,Trash2,ArrowUp,ArrowDown,Search,ListMusic} from '@lucide/svelte';
 import {assignTrack,slotEntries,swapSlots} from './mix';
 import type {Mix} from './mix';
 import {categories,filterTracks,reorder} from './catalog';
 import type {CatalogTrack} from './catalog';
 let {catalog=$bindable([]),queue=$bindable([]),theme=$bindable('dark'),selectedUrl=$bindable(''),playbackMode=$bindable('single'),mix=$bindable({base:null,layers:[]})}:{catalog?:CatalogTrack[];queue?:CatalogTrack[];theme?:string;selectedUrl?:string;playbackMode?:string;mix?:Mix}=$props();
 function durationText(t:CatalogTrack){const n=t.duration;return typeof n==='number'&&Number.isFinite(n)&&n>=0?`${Math.floor(n/60)}:${String(Math.floor(n%60)).padStart(2,'0')}`:'—'}
 let root:HTMLDivElement;let target=$state<number|null>(null);let dragFrom=$state(-1);
 function setMix(next:Mix){mix=next;emit('mixchange',{mix});notice='Mix updated'}
 function slotName(i:number){return i===0?'base':`layer ${i}`}
 let full=$derived(slotEntries(mix).slice(1).every(Boolean));
 function put(track:CatalogTrack,destination:number|'layer'){const next=assignTrack(mix,track,destination);if(next===mix)return;setMix(next);notice=`${track.title} assigned to ${destination==='layer'?'next empty layer':slotName(destination)}`;target=null}
 $effect(()=>{if(playbackMode!=='layers')target=null});
 function swap(from:number,to:number){setMix(swapSlots(mix,from,to))}
 function startDrag(e:DragEvent,index:number,kind:string){dragFrom=index;e.dataTransfer?.setData('text/plain',`${kind}:${index}`)}
 function drop(e:DragEvent,to:number,kind:string){e.preventDefault();const [type,value]=(e.dataTransfer?.getData('text/plain')||'').split(':');const from=Number(value);if(type!==kind||!Number.isInteger(from))return;if(kind==='queue')move(from,to);else swap(from,to);dragFrom=-1}
let category=$state(''),search=$state(''),notice=$state('');
 let categoryList=$derived(categories(catalog));let results=$derived(filterTracks(catalog,category,search));
 $effect(()=>{if(category&&!categoryList.includes(category))category=''});
 function emit(name:string,detail:unknown){root.dispatchEvent(new CustomEvent(name,{detail,bubbles:true,composed:true}))}
 function select(track:CatalogTrack,source:'catalog'|'queue',index:number){if(playbackMode==='layers')return;emit('trackselect',{track,source,index})}
 function update(next:CatalogTrack[],message:string){queue=next;notice=message;emit('queuechange',{queue:next})}
 function add(track:CatalogTrack){update([...queue,track],`Added ${track.title} to queue`)}
 function move(from:number,to:number){update(reorder(queue,from,to),`Moved ${queue[from].title} to position ${to+1}`)}
</script>
<div bind:this={root} class="browser" class:light={theme==='light'}>
 <section aria-label="Audio library">
  <div class="heading"><div><div class="eyebrow">YOUR COLLECTION</div><h2>Audio library</h2></div><span class="count">{catalog.length} tracks</span></div>
  <label class="mode-label">Playback mode<select aria-label="Playback mode" bind:value={playbackMode} onchange={()=>emit('modechange',{mode:playbackMode})}><option value="single">Single track</option><option value="playlist">Playlist</option><option value="layers">Layers</option></select></label>
  {#if playbackMode==='layers'}<p class="mix-help">Set a base track, then add up to three layers. Use Play on the player to start the mix.</p>{#if target!==null}<div class="choose-banner" role="status"><span>Choose a track for <strong>{slotName(target)}</strong></span><button onclick={()=>target=null}>Cancel</button></div>{/if}{/if}
  <div class="filters"><label>Category<select aria-label="Category" bind:value={category}><option value="">All categories</option>{#each categoryList as item}<option value={item}>{item}</option>{/each}</select></label><label>Search titles<div class="search"><Search size={16}/><input aria-label="Search titles" type="search" placeholder="Find a track…" bind:value={search}/></div></label></div>
  <div class="results" aria-label="Tracks">
   {#each results as track,i}<div class="row" class:active={selectedUrl===track.url}><div class="metadata"><span class="title" title={track.title}>{track.title}</span><span class="category">{track.category||'Uncategorized'} · {durationText(track)}</span></div>{#if playbackMode==='layers'}<div class="track-actions">{#if target!==null}<button class="assign" aria-label={`Use ${track.title} as ${slotName(target)}`} onclick={()=>put(track,target!)}>Use as {slotName(target)}</button>{:else}<button class="assign" aria-label={`Set ${track.title} as base`} onclick={()=>put(track,0)}>Set base</button><button class="assign accent" disabled={full} aria-label={`Add ${track.title} as layer`} onclick={()=>put(track,'layer')}>+ Layer</button>{/if}</div>{:else}<button class="icon" aria-label={`Play ${track.title}`} onclick={()=>select(track,'catalog',i)}><Play size={17} fill="currentColor"/></button><button class="icon add" aria-label={`Add ${track.title} to queue`} onclick={()=>add(track)}><Plus size={19}/></button>{/if}</div>{:else}<p class="empty">{catalog.length?'No tracks match your search.':'No audio tracks supplied yet.'}</p>{/each}
  </div>
 </section>
 {#if playbackMode==='layers'}
 <section class="queue" aria-label="Layer mix"><div class="heading"><h2>Base + layers</h2><span class="count">Drag to move or swap</span></div>
 {#each slotEntries(mix) as entry,i (entry?.id??`empty-${i}`)}<div class="mix-slot" class:choosing={target===i} role="group" aria-label={i===0?'Base slot':`Layer ${i} slot`} draggable={!!entry} ondragstart={e=>startDrag(e,i,'mix')} ondragover={e=>e.preventDefault()} ondrop={e=>drop(e,i,'mix')}><span class="slot-name">{i===0?'BASE':`LAYER ${i}`}</span><span class="slot-title">{entry?.track.title??'Empty slot'}</span><button class="assign" aria-label={`${entry?'Replace':'Choose'} ${slotName(i)}`} aria-pressed={target===i} onclick={()=>{target=i;notice=`Choose a track for ${slotName(i)} from the list above`}}>{entry?'Replace':'Choose'}</button>{#if entry}<select aria-label={`Move ${i===0?'base':`layer ${i}`} to slot`} value={i} onchange={e=>swap(i,Number(e.currentTarget.value))}>{#each [0,1,2,3] as n}<option value={n}>{n===0?'Base':`Layer ${n}`}</option>{/each}</select><button class="icon" aria-label={`Remove ${i===0?'base':`layer ${i}`}`} onclick={()=>{const a=slotEntries(mix);a[i]=null;setMix({base:a[0],layers:a.slice(1)})}}><Trash2 size={15}/></button>{/if}</div>{/each}
 </section>
 {:else}<section class="queue" aria-label="Playlist queue">
  <div class="heading"><div><div class="eyebrow">UP NEXT</div><h2><ListMusic size={19}/> Playlist queue <span class="count">{queue.length}</span></h2></div><button class="clear" disabled={!queue.length} onclick={()=>update([],'Queue cleared')}>Clear</button></div>
  <ol>{#each queue as track,i}<li class:active={selectedUrl===track.url} draggable="true" ondragstart={e=>startDrag(e,i,'queue')} ondragover={e=>e.preventDefault()} ondrop={e=>drop(e,i,'queue')}><span class="position">{i+1}</span><button class="queue-title" title={track.title} aria-label={`Play queue item ${i+1}: ${track.title}`} onclick={()=>select(track,'queue',i)}>{track.title}</button><div class="actions"><button class="icon" disabled={i===0} aria-label={`Move queue item ${i+1} up`} onclick={()=>move(i,i-1)}><ArrowUp size={15}/></button><button class="icon" disabled={i===queue.length-1} aria-label={`Move queue item ${i+1} down`} onclick={()=>move(i,i+1)}><ArrowDown size={15}/></button><button class="icon" aria-label={`Remove queue item ${i+1}`} onclick={()=>update(queue.filter((_,n)=>n!==i),`Removed ${track.title}`)}><Trash2 size={15}/></button></div></li>{:else}<li class="empty">Add tracks with + to build your playlist.</li>{/each}</ol>
 </section>
 {/if}<div class="status" role="status" aria-live="polite">{notice}</div>
</div>
<style>
.mix-help{font-size:12px;line-height:1.6;color:var(--muted);margin:14px 0 0}.choose-banner{display:flex;align-items:center;justify-content:space-between;padding:12px;background:var(--hover);border:1px solid var(--accent);border-radius:7px;font-size:12px;margin-top:12px}.choose-banner button{color:var(--accent);text-decoration:underline}.track-actions{display:flex;gap:5px}.assign{font-size:11px;padding:7px 9px;border:1px solid var(--line);border-radius:6px;white-space:nowrap}.assign:hover,.assign[aria-pressed=true]{background:var(--hover);border-color:var(--accent)}.accent{color:var(--accent)}.choosing{box-shadow:inset 2px 0 var(--accent);background:var(--hover)}.mode-label{margin-top:16px}.mix-slot{flex-wrap:wrap;user-select:none;cursor:grab;display:flex;align-items:center;gap:10px;padding:12px 0;border-bottom:1px solid var(--line)}.slot-name{font-size:9px;color:var(--accent);width:45px}.slot-title{flex-basis:150px!important;font-size:12px;flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.mix-slot select{width:82px;font-size:11px}:host{display:block;width:540px;max-width:100%;font-family:Arial,Helvetica,sans-serif}.browser{--ink:#f6f8fa;--muted:#99a7b3;--accent:#00c5df;--line:#3b454e;--field:#1d252a;--hover:#2e3b42;box-sizing:border-box;min-height:480px;color:var(--ink);background:radial-gradient(ellipse at 50% 42%,#273238,#20282c 65%,#1e2529);border:1px solid #ffffff15;border-radius:12px;padding:24px;box-shadow:0 12px 24px #0003}.light{--ink:#27323b;--muted:#667684;--accent:#008fa5;--line:#d4dbe2;--field:#f2f5f7;--hover:#e9f4f6;background:linear-gradient(130deg,#fff,#fafcfd);border-color:#e3e7eb}.heading{display:flex;align-items:center;justify-content:space-between;gap:12px}.eyebrow{font-size:10px;letter-spacing:1px;color:var(--muted)}h2{display:flex;align-items:center;gap:8px;font-size:20px;margin:7px 0 0}.count{font-size:11px;color:var(--muted);font-weight:normal}.filters{display:grid;grid-template-columns:1fr 1.5fr;gap:12px;margin:22px 0 14px}label{font-size:11px;color:var(--muted);display:flex;flex-direction:column;gap:7px}select,input{box-sizing:border-box;background:var(--field);border:1px solid var(--line);color:var(--ink);border-radius:7px;height:36px;font:inherit;font-size:13px;width:100%;min-width:0}select{padding:0 10px}input{border:0;background:transparent;padding:0 8px}.search{display:flex;align-items:center;gap:4px;padding-left:10px;border:1px solid var(--line);border-radius:7px;background:var(--field)}.results{max-height:225px;overflow:auto}.row{display:flex;gap:9px;align-items:center;padding:11px 8px;border-bottom:1px solid var(--line);border-radius:5px}.row:hover,li:hover{background:var(--hover)}.active{background:var(--hover);box-shadow:inset 2px 0 var(--accent)}.metadata{display:flex;flex-direction:column;gap:5px;flex:1;min-width:0}.title{font-size:13px;font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.category{font-size:10px;color:var(--muted)}button{font:inherit;color:var(--ink);border:0;background:transparent;cursor:pointer}.icon{display:inline-flex;align-items:center;justify-content:center;width:28px;height:28px;border-radius:6px;flex-shrink:0}.icon:hover{background:var(--line)}.add{color:var(--accent)}button:disabled{opacity:.3;cursor:default}button:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid var(--accent);outline-offset:2px}.queue{border-top:1px solid var(--line);margin-top:23px;padding-top:20px}.queue h2{font-size:16px}.clear{font-size:11px;color:var(--muted)}ol{list-style:none;padding:0;margin:14px 0 0;max-height:210px;overflow:auto}li{display:flex;align-items:center;gap:8px;padding:7px 5px;border-radius:5px}.position{color:var(--muted);font-size:11px;width:16px;text-align:center;flex-shrink:0}.queue-title{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;text-align:left;font-size:12px;padding:5px 0}.actions{display:flex;gap:1px}.empty{font-size:12px;color:var(--muted);padding:18px 5px;line-height:1.5}.status{min-height:14px;margin-top:12px;font-size:10px;color:var(--muted)}
</style>
